function describe(value: string | number | boolean): string {
  return "";
}

referenceSolution:
function describe(value: string | number | boolean): string {
  if (typeof value === "string") return "teks: " + value.toUpperCase();
  if (typeof value === "number") return "angka: " + value.toFixed(2);
  return value ? "ya" : "tidak";
}
